-- ============================================================
-- Holotisch C25: AI summary per own exemplar.
--
-- An "exemplar" is one hangar_ship_configs row (one named loadout of an owned ship). The one-line summary the hangar
-- menu shows ("Laser-Jäger mit Distortion-Sekundär, mehr Kühlung", <= 90 chars) is generated by the `exemplar-ai`
-- edge function and stored here together with a hash of the loadout it was made from; the client regenerates it only
-- when the current loadout hash differs from ai_summary_hash.
--
--   ai_summary      the text, null = never generated (UI shows the empty state, no fake text)
--   ai_summary_hash stable hash of the loadout the text describes (client `loadoutHash()`)
--   ai_summary_at   when it was generated
--
-- ADDITIVE and nullable: no backfill, drops nothing. RLS is unchanged - the existing owner-only policies on
-- hangar_ship_configs already cover these columns (the owner writes the summary of their own exemplar).
-- ============================================================

alter table public.hangar_ship_configs
  add column if not exists ai_summary text,
  add column if not exists ai_summary_hash text,
  add column if not exists ai_summary_at timestamptz;

alter table public.hangar_ship_configs
  drop constraint if exists hangar_ship_configs_ai_summary_len;
alter table public.hangar_ship_configs
  add constraint hangar_ship_configs_ai_summary_len check (ai_summary is null or char_length(ai_summary) <= 200);

comment on column public.hangar_ship_configs.ai_summary is
  'One-line AI summary of this exemplar''s loadout (<= 90 chars by the function, <= 200 by constraint). Null = not generated.';
comment on column public.hangar_ship_configs.ai_summary_hash is
  'Hash of the loadout ai_summary was generated from; regenerate only when the current loadout hash differs.';
comment on column public.hangar_ship_configs.ai_summary_at is 'When ai_summary was generated.';
